<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Plus, ArrowUp, ArrowDown, Trash2, Save, CircleCheck } from '@lucide/vue'
import { api } from './session'
import type { List, TestItem, TestRecord } from './domain'
const route = useRoute(), router = useRouter(), isNew = computed(() => !route.params.id)
const form = reactive({ title: '', description: '', minutes: 20, pass_percent: '70.00', shuffle_questions: true, shuffle_options: false, show_candidate_score: false, items: [] as TestItem[] })
const record = ref<TestRecord | null>(null), selectedVersion = ref(0), available = ref<TestItem[]>([]), search = ref(''), sourcePage = ref(1), sourceTotal = ref(0), sourceError = ref(''), error = ref(''), notice = ref(''), loading = ref(false), busy = ref(false), baseline = ref('')
const archived = computed(() => record.value?.status === 'archived')
function payload() { return { title: form.title, description: form.description, duration_seconds: Math.round(form.minutes * 60), pass_percent: form.pass_percent.replace(',', '.'), shuffle_questions: form.shuffle_questions, shuffle_options: form.shuffle_options, show_candidate_score: form.show_candidate_score, items: form.items.map(i => ({ question_version_id: i.question_version_id, points: i.points.replace(',', '.') })), base_version_no: record.value?.latest_version_no || 0 } }
const dirty = computed(() => JSON.stringify(payload()) !== baseline.value)
const totalPoints = computed(() => (form.items.reduce((n, i) => n + Math.round(Number(i.points.replace(',', '.')) * 100 || 0), 0) / 100).toFixed(2))
onBeforeRouteLeave(() => !dirty.value || busy.value || window.confirm('В тесте есть несохранённые изменения. Покинуть конструктор?'))
let generation = 0, sourceGeneration = 0
async function load(version = 0) {
  const current = ++generation; error.value = ''; loading.value = true
  if (isNew.value) { record.value = null; Object.assign(form, { title: '', description: '', minutes: 20, pass_percent: '70.00', shuffle_questions: true, shuffle_options: false, show_candidate_score: false, items: [] }); baseline.value = JSON.stringify(payload()); loading.value = false; return }
  try { const data = await api<TestRecord>('/tests/' + route.params.id + (version ? '?version_no=' + version : '')); if (current !== generation) return; record.value = data; selectedVersion.value = data.version_no; Object.assign(form, { title: data.title, description: data.description, minutes: data.duration_seconds / 60, pass_percent: data.pass_percent, shuffle_questions: data.shuffle_questions, shuffle_options: data.shuffle_options, show_candidate_score: data.show_candidate_score, items: data.items.map(i => ({ ...i })) }); baseline.value = JSON.stringify(payload()) }
  catch (err) { if (current === generation) error.value = (err as Error).message } finally { if (current === generation) loading.value = false }
}
async function loadSources() {
  const current = ++sourceGeneration; sourceError.value = ''
  try { const data = await api<List<TestItem>>('/question-versions?' + new URLSearchParams({ search: search.value, page: String(sourcePage.value) })); if (current === sourceGeneration) { available.value = data.items; sourceTotal.value = data.total } }
  catch (err) { if (current === sourceGeneration) sourceError.value = (err as Error).message }
}
function add(item: TestItem) { if (!form.items.some(i => i.question_id === item.question_id) && form.items.length < 200) form.items.push({ ...item, points: '1.00' }) }
function move(index: number, delta: number) { const [item] = form.items.splice(index, 1); form.items.splice(index + delta, 0, item!) }
async function save() {
  error.value = ''; notice.value = ''; busy.value = true
  try { const data = await api<{ id: string; version_no: number }>('/tests' + (isNew.value ? '' : '/' + route.params.id + '/versions'), { method: 'POST', body: JSON.stringify(payload()) }); if (isNew.value) await router.replace('/tests/' + data.id + '/edit'); else await load(); notice.value = 'Версия теста ' + data.version_no + ' сохранена.' }
  catch (err) { error.value = (err as Error).message } finally { busy.value = false }
}
async function publish() {
  if (!record.value || dirty.value) return; busy.value = true; error.value = ''; notice.value = ''
  try { await api('/tests/' + route.params.id + '/publish', { method: 'POST', body: JSON.stringify({ base_version_no: record.value.latest_version_no }) }); await load(); notice.value = 'Тест опубликован. Теперь можно выдать приглашение.' }
  catch (err) { error.value = (err as Error).message } finally { busy.value = false }
}
async function archive() {
  if (!window.confirm('Переместить тест в архив? Новые приглашения будут запрещены. Ранее выданные ссылки сохранят срок действия.')) return
  busy.value = true; error.value = ''; try { await api('/tests/' + route.params.id + '/archive', { method: 'POST' }); await router.push('/tests') } catch (err) { error.value = (err as Error).message } finally { busy.value = false }
}
function selectVersion() { if (dirty.value && !window.confirm('Несохранённые изменения будут потеряны. Открыть другую версию?')) { selectedVersion.value = record.value!.version_no; return }; notice.value = ''; load(selectedVersion.value) }
watch(() => route.params.id, () => load()); onMounted(() => { load(); loadSources() })
</script>
<template>
  <RouterLink to="/tests" class="back-link"><ArrowLeft :size="17" />К списку тестов</RouterLink>
  <div class="page-heading"><div><p class="eyebrow">КОНСТРУКТОР</p><h1>{{ isNew ? 'Новый тест' : 'Конструктор теста' }}</h1><p class="subtitle">Выберите вопросы, задайте порядок и правила прохождения.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-success" role="status">{{ notice }}</p><p v-if="loading" class="loading-state" role="status">Загружаем тест…</p>
  <template v-else>
    <div v-if="record" class="version-strip"><span class="status-pill" :class="archived ? 'archived' : record.version_status === 'published' ? 'active' : 'draft'">{{ archived ? 'В архиве' : record.version_status === 'published' ? 'Опубликован' : 'Черновик' }}</span><label>Версия <select v-model="selectedVersion" aria-label="Версия теста" @change="selectVersion"><option v-for="v in record.versions" :key="v.version_no" :value="v.version_no">{{ v.version_no }} — {{ v.status === 'published' ? 'опубликована' : 'черновик' }}</option></select></label><span v-if="selectedVersion !== record.latest_version_no">Историческая версия. Сохранение создаст новую.</span></div>
    <form class="editor-layout" @submit.prevent="save"><div class="editor-main"><section class="editor-card"><h2>О тесте</h2><label class="form-field">Название теста<input v-model="form.title" required maxlength="250" :disabled="archived" placeholder="Например, логическое мышление" /></label><label class="form-field">Описание теста<textarea v-model="form.description" rows="3" maxlength="10000" :disabled="archived" /></label></section>
      <section class="editor-card"><div class="section-heading"><h2>Состав теста</h2><span class="small-label">{{ form.items.length }} ВОПРОСОВ</span></div><p v-if="!form.items.length" class="muted-text">Добавьте вопросы из банка ниже. Пустой черновик можно сохранить, но нельзя опубликовать.</p><article v-for="(item, index) in form.items" :key="item.question_version_id" class="test-item-row"><div class="test-item-heading"><span class="step-number">{{ index + 1 }}</span><div><h3>{{ item.body }}</h3><span class="field-hint">Версия вопроса {{ item.question_version_no }}</span></div></div><div class="test-item-controls"><label class="form-field">Вес<input v-model="item.points" :aria-label="'Вес вопроса ' + (index + 1)" inputmode="decimal" required pattern="[0-9]+([.,][0-9]{1,2})?" :disabled="archived" /></label><button type="button" class="icon-button" :disabled="archived || index === 0" :aria-label="'Поднять вопрос ' + (index + 1)" @click="move(index, -1)"><ArrowUp :size="17" /></button><button type="button" class="icon-button" :disabled="archived || index === form.items.length - 1" :aria-label="'Опустить вопрос ' + (index + 1)" @click="move(index, 1)"><ArrowDown :size="17" /></button><button type="button" class="icon-button danger" :disabled="archived" :aria-label="'Убрать вопрос ' + (index + 1)" @click="form.items.splice(index, 1)"><Trash2 :size="17" /></button></div></article></section>
      <section v-if="!archived" class="editor-card"><h2>Добавить из банка вопросов</h2><p class="muted-text">Только опубликованные редакции. Новая редакция вопроса не заменит уже выбранную.</p><div class="search-field"><input v-model="search" aria-label="Поиск вопросов для теста" placeholder="Найти опубликованный вопрос…" maxlength="200" @keydown.enter.prevent="sourcePage = 1; loadSources()" /><button type="button" class="text-button" @click="sourcePage = 1; loadSources()">Найти</button></div><p v-if="sourceError" class="form-error" role="alert">{{ sourceError }}</p><div v-for="item in available" :key="item.question_version_id" class="source-question"><div><p>{{ item.body }}</p><span class="field-hint">Версия {{ item.question_version_no }}</span></div><button type="button" class="secondary-button" :disabled="form.items.some(i => i.question_id === item.question_id) || form.items.length >= 200" :aria-label="'Добавить вопрос: ' + item.body" @click="add(item)"><Plus :size="16" />Добавить</button></div><p v-if="!available.length && !sourceError" class="muted-text">Нет опубликованных вопросов. Сначала опубликуйте их в банке.</p><div v-if="sourceTotal > 20" class="pagination"><button type="button" class="secondary-button" :disabled="sourcePage <= 1" @click="sourcePage--; loadSources()">Назад</button><span>{{ sourcePage }}</span><button type="button" class="secondary-button" :disabled="sourcePage * 20 >= sourceTotal" @click="sourcePage++; loadSources()">Далее</button></div></section></div>
      <aside class="editor-side"><section class="editor-card"><h2>Прохождение</h2><label class="form-field">Время, минут<input v-model.number="form.minutes" type="number" min="1" max="480" step="any" required :disabled="archived" /></label><label class="form-field">Проходной процент<input v-model="form.pass_percent" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required :disabled="archived" /></label><label class="check-field"><input v-model="form.shuffle_questions" type="checkbox" :disabled="archived" />Перемешивать вопросы</label><label class="check-field"><input v-model="form.shuffle_options" type="checkbox" :disabled="archived" />Перемешивать варианты</label><label class="check-field"><input v-model="form.show_candidate_score" type="checkbox" :disabled="archived" />Показывать итог кандидату</label><p class="muted-text">{{ form.items.length }} вопросов · {{ totalPoints }} баллов</p><button class="primary-link" :disabled="busy || archived"><Save :size="17" />{{ busy ? 'Сохраняем…' : isNew ? 'Сохранить тест' : 'Сохранить новую версию теста' }}</button><button v-if="record && !archived" type="button" class="secondary-button" :disabled="busy || dirty || record.version_status === 'published' || selectedVersion !== record.latest_version_no" @click="publish"><CircleCheck :size="17" />Опубликовать тест</button><p v-if="record && dirty" class="field-hint">Сохраните изменения перед публикацией.</p><RouterLink v-if="record?.version_status === 'published' && !archived && !dirty" :to="'/invitations?test_id=' + record.id + '&test_version_no=' + record.version_no" class="primary-link">Выдать приглашение</RouterLink><button v-if="record && !archived" type="button" class="text-button danger" :disabled="busy" @click="archive">Архивировать тест</button></section></aside>
    </form>
  </template>
</template>
